<script setup>
import{computed,onMounted,ref}from'vue';import{selfEvaluationApi as api}from'../../selfEvaluationApi'
const tasks=ref([]),task=ref(null),form=ref(null),warnings=ref([]),reminders=ref([]),message=ref(''),msgType=ref('info'),loading=ref(false),running=ref(false)
const openCount=computed(()=>warnings.value.filter(x=>x.status==='OPEN').length)
function msg(text,type='info'){message.value=text;msgType.value=type;if(type!=='error')setTimeout(()=>{if(message.value===text)message.value=''},4000)}
async function load(){try{loading.value=true;let results=await Promise.allSettled([api.tasks(),api.warnings(),api.reminders()]);tasks.value=results[0].status==='fulfilled'?results[0].value:[];warnings.value=results[1].status==='fulfilled'?results[1].value:[];reminders.value=results[2].status==='fulfilled'?results[2].value:[];if(results.some(r=>r.status==='rejected'))msg('部分数据加载失败，请确认后端已启动','error')}catch(e){msg(e.message||'加载失败','error')}finally{loading.value=false}}
async function selectTask(id){if(!id)return;try{task.value=await api.task(id);form.value=null;msg('')}catch(e){msg(e.message,'error')}}
async function selectForm(id){if(!id||!task.value)return;try{const org=task.value.organizations.find(x=>x.id==id);if(!org)return;form.value=await api.form(org.id);msg('')}catch(e){msg(e.message,'error')}}
async function requirement(x){const count=Number(prompt('必传材料数量',x.required_material_count||1));if(isNaN(count)||count<0){msg('请输入有效数量','error');return}const allowed=prompt('允许格式（逗号分隔）',x.allowed_extensions||'pdf,docx');const keywords=prompt('命名关键词（逗号分隔，选填）',x.naming_keywords||'');const due=prompt('截止日期 YYYY-MM-DD（选填）',x.due_date||'');try{await api.requirement(x.snapshot_id,{requiredMaterialCount:count,allowedExtensions:allowed,namingKeywords:keywords,dueDate:due});form.value=await api.form(form.value.id);msg('材料要求已更新','success')}catch(e){msg(e.message,'error')}}
async function run(){if(!task.value){msg('请先选择自评任务','error');return}running.value=true;try{const orgId=form.value?.org_unit_id||'';const r=await api.runWarnings(task.value.id,orgId);msg(`规则检查完成：检查${r.totalChecks}项，触发${r.warningCount}条预警`,'success');await load()}catch(e){msg(e.message,'error')}finally{running.value=false}}
async function processWarning(x,status){const opinion=prompt(status==='RESOLVED'?'处理说明':'处理意见');if(!opinion)return;try{await api.processWarning(x.id,{status,opinion});msg(`预警已${status==='RESOLVED'?'解决':status==='CONFIRMED'?'确认':status==='IGNORED'?'忽略':'处理'}`,status!=='OPEN'?'success':'info');await load()}catch(e){msg(e.message,'error')}}
async function remind(x){try{await api.remind(x.id);msg('本地模拟提醒已记录（未发送真实短信）','success');await load()}catch(e){msg(e.message,'error')}}
onMounted(load)
</script>
<template><section class="page active"><div class="alert alert-warning">⚠️ 本页执行确定性"规则检查"，不使用AI。提醒仅写入本地日志，不发送真实短信。 <span v-if="loading" style="margin-left:8px">⏳ 加载中...</span></div><div v-if="message" class="alert" :class="msgType==='error'?'alert-danger':msgType==='success'?'alert-success':'alert-info'">{{message}}</div>
<div class="stat-grid"><div class="stat-card"><div class="num">{{warnings.length}}</div><div class="label">历史预警总数</div><div class="sub">所有规则检查记录</div></div><div class="stat-card"><div class="num" :class="openCount>0?'red':'green'">{{openCount}}</div><div class="label">待处理预警</div><div class="sub">需要关注和处理</div></div><div class="stat-card"><div class="num">{{reminders.length}}</div><div class="label">模拟提醒次数</div><div class="sub">本地日志记录</div></div><div class="stat-card"><div class="num green">{{warnings.filter(x=>x.status==='RESOLVED').length}}</div><div class="label">已解决</div></div></div>
<div class="card"><div class="card-header"><h3>⚙️ 材料要求与规则检查</h3><div class="btn-group"><button class="btn btn-primary" :disabled="!task||running" @click="run">{{running?'检查中...':'执行规则检查'}}</button><button class="btn btn-outline" @click="load">刷新</button></div></div><div class="search-bar"><div class="form-item"><label>自评任务</label><select @change="selectTask($event.target.value)"><option value="">— 选择自评任务 —</option><option v-for="x in tasks" :key="x.id" :value="x.id">{{x.task_name}}（{{x.status}}）</option></select></div><div v-if="task" class="form-item"><label>参评机构（可选，不选则检查全部）</label><select @change="selectForm($event.target.value)"><option value="">— 全部机构 —</option><option v-for="x in task.organizations" :key="x.id" :value="x.id">{{x.unit_name}}（{{x.status}}）</option></select></div></div>
<div v-if="!tasks.length&&!loading" class="empty" style="padding:24px;text-align:center;color:#999">暂无自评任务。请先在"自评任务管理"(m2-12)中创建并发布自评任务。</div>
<div v-if="form" class="card"><div class="card-header"><h3>{{form.unit_name}} · 材料要求配置</h3><span class="extra">设置每个指标的必传材料规则</span></div><table><thead><tr><th>指标</th><th>标准分</th><th>必传数</th><th>允许格式</th><th>命名关键词</th><th>截止日期</th><th>操作</th></tr></thead><tbody><tr v-for="x in form.entries" :key="'rq'+x.id"><td><strong>{{x.indicator_code}}</strong> {{x.indicator_name}}</td><td>{{x.standard_score}}</td><td>{{x.required_material_count||1}}</td><td style="font-size:12px">{{x.allowed_extensions||'pdf,docx'}}</td><td>{{x.naming_keywords||'—'}}</td><td>{{x.due_date||'—'}}</td><td><button class="btn btn-sm btn-outline" @click="requirement(x)">配置规则</button></td></tr></tbody></table></div></div>
<div class="card"><div class="card-header"><h3>🚨 完整性预警历史</h3><span class="extra">所有规则检查记录</span></div><table><thead><tr><th>机构</th><th>指标</th><th>预警类型</th><th>预警信息</th><th>状态</th><th>检查时间</th><th>操作</th></tr></thead><tbody><tr v-if="loading&&!warnings.length"><td colspan="7" class="empty-cell">正在加载预警数据...</td></tr><tr v-else-if="!warnings.length"><td colspan="7" class="empty-cell">暂无规则预警。选择任务后点击"执行规则检查"。</td></tr><tr v-for="x in warnings" :key="'w'+x.id"><td>{{x.unit_name||'—'}}</td><td>{{x.indicator_code}} {{x.indicator_name}}</td><td><span class="tag" :class="x.warning_type==='MISSING'?'tag-danger':x.warning_type==='OVERDUE'?'tag-danger':x.warning_type==='FORMAT'?'tag-warning':x.warning_type==='INSUFFICIENT'?'tag-warning':'tag-info'">{{x.warning_type}}</span></td><td style="max-width:200px;overflow:hidden;text-overflow:ellipsis">{{x.message}}</td><td><span class="tag" :class="x.status==='OPEN'?'tag-danger':x.status==='RESOLVED'?'tag-success':x.status==='IGNORED'?'tag-default':'tag-info'">{{x.status}}</span></td><td style="font-size:12px">{{x.run_at||'—'}}</td><td><div class="btn-group" style="gap:4px"><button v-if="x.status==='OPEN'" class="btn btn-sm btn-primary" @click="processWarning(x,'RESOLVED')">解决</button><button v-if="x.status==='OPEN'" class="btn btn-sm btn-outline" @click="processWarning(x,'CONFIRMED')">确认</button><button v-if="x.status==='OPEN'" class="btn btn-sm btn-outline" @click="processWarning(x,'IGNORED')">忽略</button><button v-if="x.status==='OPEN'" class="btn btn-sm btn-outline" @click="remind(x)">📬 模拟提醒</button><span v-if="x.status!=='OPEN'" class="tag tag-info">已处理</span></div></td></tr></tbody></table></div>
<div v-if="reminders.length" class="card"><div class="card-header"><h3>📬 本地模拟提醒日志</h3></div><table><thead><tr><th>预警</th><th>接收人</th><th>内容</th><th>渠道</th><th>时间</th></tr></thead><tbody><tr v-for="x in reminders" :key="'r'+x.id"><td>{{x.message||'—'}}</td><td>{{x.recipient||'模拟经办人'}}</td><td>{{x.content}}</td><td><span class="tag tag-warning">{{x.channel||'LOCAL_SIMULATION'}}</span></td><td style="font-size:12px">{{x.sent_at}}</td></tr></tbody></table></div>
</section></template>
<style scoped>.empty-cell{text-align:center;color:#999;padding:24px!important}.btn-group{display:flex;gap:8px;flex-wrap:wrap}</style>
